package com.primehr.learningdevelopment.participation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="ld_enrollment",uniqueConstraints=@UniqueConstraint(name="uk_ld_enrollment_nomination",columnNames={"agency_id","nomination_id"}))
public class LdEnrollment extends RspAuditedEntity {public enum Status{INVITED,CONFIRMED,DECLINED,CANCELLED,SUBSTITUTED}@Column(name="nomination_id",nullable=false,length=36)private String nominationId;@Column(name="offering_id",nullable=false,length=36)private String offeringId;@Column(name="offering_version",nullable=false)private int offeringVersion;@Column(name="offering_fingerprint",nullable=false,length=64)private String offeringFingerprint;@Column(name="employee_id",nullable=false)private Long employeeId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name",nullable=false,length=300)private String employeeName;@Column(name="appointment_id",nullable=false)private Long appointmentId;@Column(name="employee_fingerprint",nullable=false,length=64)private String employeeFingerprint;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="confirmed_at")private Instant confirmedAt;@Column(name="cancelled_at")private Instant cancelledAt;@Column(name="status_reason",length=2000)private String statusReason;@Column(name="replaces_enrollment_id",length=36)private String replacesEnrollmentId;@Column(name="replaced_by_enrollment_id",length=36)private String replacedByEnrollmentId;protected LdEnrollment(){}public LdEnrollment(String agency,String nomination,String offering,int offeringVersion,String offeringFingerprint,Long employeeId,String employeeNo,String employeeName,Long appointmentId,String employeeFingerprint){super(agency);nominationId=requiredText(nomination,"nominationId");offeringId=requiredText(offering,"offeringId");this.offeringVersion=offeringVersion;this.offeringFingerprint=requiredText(offeringFingerprint,"offeringFingerprint");this.employeeId=employeeId;this.employeeNo=requiredText(employeeNo,"employeeNo");this.employeeName=requiredText(employeeName,"employeeName");this.appointmentId=appointmentId;this.employeeFingerprint=requiredText(employeeFingerprint,"employeeFingerprint");status=Status.INVITED;}public void confirm(Instant at){if(status!=Status.INVITED)throw new IllegalStateException("Only invited enrollment may be confirmed");status=Status.CONFIRMED;confirmedAt=at;}public void decline(String reason,Instant at){if(status!=Status.INVITED)throw new IllegalStateException("Only invited enrollment may be declined");status=Status.DECLINED;statusReason=requiredText(reason,"reason");cancelledAt=at;}public void cancel(String reason,Instant at){if(status!=Status.INVITED&&status!=Status.CONFIRMED)throw new IllegalStateException("Only active enrollment may be cancelled");status=Status.CANCELLED;statusReason=requiredText(reason,"reason");cancelledAt=at;}public void substituteWith(LdEnrollment replacement,String reason,Instant at){if(status!=Status.INVITED&&status!=Status.CONFIRMED)throw new IllegalStateException("Only active enrollment may be substituted");if(replacement==null||replacement.getStatus()!=Status.INVITED)throw new IllegalArgumentException("Replacement must be an independently approved invited enrollment");status=Status.SUBSTITUTED;statusReason=requiredText(reason,"reason");cancelledAt=at;replacedByEnrollmentId=replacement.getId();replacement.replacesEnrollmentId=getId();}public String getNominationId(){return nominationId;}public String getOfferingId(){return offeringId;}public int getOfferingVersion(){return offeringVersion;}public String getOfferingFingerprint(){return offeringFingerprint;}public Long getEmployeeId(){return employeeId;}public String getEmployeeNo(){return employeeNo;}public String getEmployeeName(){return employeeName;}public Long getAppointmentId(){return appointmentId;}public String getEmployeeFingerprint(){return employeeFingerprint;}public Status getStatus(){return status;}public Instant getConfirmedAt(){return confirmedAt;}public Instant getCancelledAt(){return cancelledAt;}public String getStatusReason(){return statusReason;}public String getReplacesEnrollmentId(){return replacesEnrollmentId;}public String getReplacedByEnrollmentId(){return replacedByEnrollmentId;}}
